from __future__ import annotations  # Enable compact type annotations for the postprocessing script.
import csv  # Read solved adaptive states and write the extracted Pareto points and fitted tail values.
import math  # Evaluate logarithms, exponentials, and logarithmically spaced extrapolation coordinates.
from pathlib import Path  # Resolve result paths portably on the GitHub Actions runner.
import matplotlib.pyplot as plt  # Draw the requested script-generated scatter and Pareto curves.

ROOT = Path(__file__).resolve().parent  # Anchor all input and output paths to the long-run experiment directory.
RESULTS_DIR = ROOT / "results"  # Read the numerical history and write all plotting artifacts in the compact result directory.
HISTORY_PATH = RESULTS_DIR / "history.csv"  # Read the actual solved DOF-error points produced by the long-run numerical benchmark.
PLOT_PATH = RESULTS_DIR / "pareto_longrun.png"  # Save the main user-requested scatter and Pareto-curve figure as a PNG artifact.
PARETO_PATH = RESULTS_DIR / "pareto_points.csv"  # Save the actual nondominated solved points used to draw each method's Pareto line.
FIT_PATH = RESULTS_DIR / "tail_fit.csv"  # Save the fitted tail exponents and large-DOF extrapolated values for auditability.
EXTRAPOLATION_MAX_DOF = 10_000_000.0  # Extend only the fitted dashed trends to a very large finite DOF as a visual proxy for the asymptotic direction.
TAIL_POINT_COUNT = 5  # Fit each asymptotic power law using the last five actual Pareto points when that many points are available.


def read_history() -> dict[str, list[tuple[float, float, int]]]:  # Read actual solved states grouped by adaptive method.
    grouped: dict[str, list[tuple[float, float, int]]] = {}  # Store tuples of DOF, relative error, and adaptive round for each method.
    with HISTORY_PATH.open("r", encoding="utf-8", newline="") as handle:  # Open the compact numerical history generated by GitHub Actions.
        reader = csv.DictReader(handle)  # Parse the stable CSV schema written by the numerical benchmark.
        for row in reader:  # Traverse every solved global and semantic adaptive state.
            method = row["method"]  # Read the method identifier exactly as written by the benchmark.
            dof = float(row["dof"])  # Convert the resource coordinate to a numeric value for sorting and plotting.
            error = float(row["qoi_rel_error"])  # Convert the QoI relative error to a numeric value for Pareto analysis.
            round_index = int(row["round"])  # Preserve the adaptive round so actual scatter points can be audited later.
            if error > 0.0:  # Exclude only exact-zero values because logarithmic plotting and tail fitting require positive errors.
                grouped.setdefault(method, []).append((dof, error, round_index))  # Append the current actual solved point to its method trajectory.
    return grouped  # Return all actual solved states grouped by method.


def pareto_front(points: list[tuple[float, float, int]]) -> list[tuple[float, float, int]]:  # Extract nondominated error-versus-DOF points from one method's solved history.
    ordered = sorted(points, key=lambda item: (item[0], item[1]))  # Sort states by increasing resource and then increasing error.
    frontier: list[tuple[float, float, int]] = []  # Accumulate points whose error improves on every cheaper solved state.
    best_error = math.inf  # Track the smallest error observed at any lower or equal DOF.
    for point in ordered:  # Traverse solved states from low resource to high resource.
        if point[1] < best_error:  # Keep the state only when it provides a genuine new accuracy improvement.
            frontier.append(point)  # Add the current nondominated state to the Pareto frontier.
            best_error = point[1]  # Update the best accuracy achievable with no more than the current resource.
    return frontier  # Return the actual solved Pareto points in increasing-DOF order.


def fit_power_law(points: list[tuple[float, float, int]]) -> tuple[float, float]:  # Fit error approximately equal to coefficient times DOF raised to an exponent on the tail.
    tail = points[-min(TAIL_POINT_COUNT, len(points)):]  # Select only the last few actual Pareto points to represent the asymptotic regime.
    xs = [math.log(point[0]) for point in tail]  # Transform actual DOF values to logarithmic coordinates for linear least squares.
    ys = [math.log(point[1]) for point in tail]  # Transform positive relative errors to logarithmic coordinates for linear least squares.
    mean_x = sum(xs) / len(xs)  # Compute the mean logarithmic DOF coordinate used by the regression formula.
    mean_y = sum(ys) / len(ys)  # Compute the mean logarithmic error coordinate used by the regression formula.
    denominator = sum((value - mean_x) ** 2 for value in xs)  # Compute the logarithmic DOF variance term in the least-squares slope.
    exponent = 0.0 if denominator == 0.0 else sum((x_value - mean_x) * (y_value - mean_y) for x_value, y_value in zip(xs, ys)) / denominator  # Compute the fitted log-log slope, which is the power-law exponent.
    intercept = mean_y - exponent * mean_x  # Compute the fitted log-space intercept after the slope has been determined.
    coefficient = math.exp(intercept)  # Convert the fitted intercept back to the positive multiplicative power-law coefficient.
    return coefficient, exponent  # Return the fitted asymptotic power-law parameters.


def logspace(start: float, stop: float, count: int) -> list[float]:  # Generate logarithmically spaced DOF coordinates without adding a NumPy dependency.
    log_start = math.log(start)  # Convert the lower positive DOF bound to natural-log space.
    log_stop = math.log(stop)  # Convert the upper positive DOF bound to natural-log space.
    return [math.exp(log_start + (log_stop - log_start) * index / (count - 1)) for index in range(count)]  # Interpolate uniformly in log space and transform each coordinate back to DOF space.


def write_pareto_csv(frontiers: dict[str, list[tuple[float, float, int]]]) -> None:  # Persist every actual nondominated solved point used by the plotted Pareto curves.
    with PARETO_PATH.open("w", encoding="utf-8", newline="") as handle:  # Open the compact Pareto-point table with portable CSV newline handling.
        writer = csv.DictWriter(handle, fieldnames=["method", "round", "dof", "qoi_rel_error"])  # Define a stable schema for actual Pareto points.
        writer.writeheader()  # Emit the column header before any numerical points.
        for method, points in frontiers.items():  # Traverse each method's extracted nondominated actual states.
            for dof, error, round_index in points:  # Traverse actual Pareto states in increasing-resource order.
                writer.writerow({"method": method, "round": round_index, "dof": dof, "qoi_rel_error": error})  # Write one actual nondominated point exactly as used by the figure.


def main() -> int:  # Build the script-generated actual scatter, Pareto frontiers, and clearly marked asymptotic extrapolations.
    grouped = read_history()  # Load all actual solved long-run states from the GitHub Actions numerical output.
    frontiers = {method: pareto_front(points) for method, points in grouped.items()}  # Extract each method's actual nondominated error-versus-resource trajectory.
    write_pareto_csv(frontiers)  # Persist the exact actual Pareto points before any curve fitting or extrapolation is performed.
    plt.rcParams["font.sans-serif"] = ["Noto Sans CJK SC", "DejaVu Sans"]  # Prefer an installed Chinese font while retaining a standard fallback for runner portability.
    plt.rcParams["axes.unicode_minus"] = False  # Render negative signs correctly when Chinese font fallback is active.
    figure, axis = plt.subplots(figsize=(12, 7))  # Create one standalone plot because the user requested a direct scatter/Pareto figure rather than multiple subplots.
    fit_records: list[dict[str, float | str]] = []  # Accumulate fitted tail parameters and large-DOF predictions for a transparent numerical summary.
    for method, points in grouped.items():  # Draw every method using actual solved states first.
        sorted_points = sorted(points, key=lambda item: item[0])  # Sort actual states by increasing DOF so annotations and line segments remain readable.
        actual_dof = [point[0] for point in sorted_points]  # Extract actual solved resource coordinates for the scatter layer.
        actual_error = [point[1] for point in sorted_points]  # Extract actual solved QoI errors for the scatter layer.
        scatter_handle = axis.scatter(actual_dof, actual_error, s=42, label=f"{method} 实算点")  # Draw only actual CalculiX/Gmsh states as visible scatter markers.
        frontier = frontiers[method]  # Retrieve the nondominated subset of actual solved states for this method.
        frontier_dof = [point[0] for point in frontier]  # Extract actual Pareto resource coordinates for the solid frontier line.
        frontier_error = [point[1] for point in frontier]  # Extract actual Pareto errors for the solid frontier line.
        axis.plot(frontier_dof, frontier_error, marker="o", label=f"{method} 实算 Pareto")  # Connect actual nondominated states with a solid line without inventing intermediate numerical solves.
        if len(frontier) >= 3:  # Fit an asymptotic trend only when enough actual Pareto states exist for a meaningful tail regression.
            coefficient, exponent = fit_power_law(frontier)  # Fit a simple power law to the last few actual nondominated states in log-log coordinates.
            extrapolation_dof = logspace(frontier_dof[-1], EXTRAPOLATION_MAX_DOF, 100)  # Generate large-resource coordinates only beyond the final actual solved state.
            extrapolation_error = [coefficient * value ** exponent for value in extrapolation_dof]  # Evaluate the fitted asymptotic trend at each large-resource coordinate.
            axis.plot(extrapolation_dof, extrapolation_error, linestyle="--", alpha=0.75, label=f"{method} 尾部拟合外推")  # Draw the extrapolation as a dashed line so it cannot be confused with actual solver output.
            predicted_error = coefficient * EXTRAPOLATION_MAX_DOF ** exponent  # Evaluate the fitted trend at the displayed maximum extrapolated DOF.
            fit_records.append({"method": method, "coefficient": coefficient, "exponent": exponent, "predicted_error_at_1e7_dof": predicted_error})  # Preserve the fitted asymptotic parameters and one large-resource prediction for interpretation.
    axis.set_xscale("log")  # Use a logarithmic resource axis so both early and very large DOF regimes remain visible on one figure.
    axis.set_yscale("log")  # Use a logarithmic error axis so convergence rates appear approximately linear under power-law behavior.
    axis.set_xlabel("DOF（资源，对数坐标）")  # Label the horizontal resource coordinate in Chinese for immediate interpretation.
    axis.set_ylabel("QoI 相对误差（对数坐标）")  # Label the vertical accuracy coordinate in Chinese for immediate interpretation.
    axis.set_title("长序列 Pareto 散点：实算到 12 轮，虚线仅为尾部趋势外推")  # State explicitly which curve segments are actual solves and which are fitted extrapolations.
    axis.grid(True, which="both", alpha=0.25)  # Add light logarithmic grid lines to make order-of-magnitude comparisons easier without dominating the data.
    axis.legend(fontsize=8)  # Show separate legend entries for actual scatter, actual Pareto fronts, and dashed extrapolations.
    figure.tight_layout()  # Use the available canvas efficiently while avoiding clipped Chinese axis labels and legend text.
    figure.savefig(PLOT_PATH, dpi=220)  # Save the requested script-generated high-resolution scatter/Pareto figure for the Actions artifact.
    plt.close(figure)  # Release the plotting resources explicitly after the PNG has been written.
    with FIT_PATH.open("w", encoding="utf-8", newline="") as handle:  # Open a compact table for the fitted asymptotic trend parameters.
        writer = csv.DictWriter(handle, fieldnames=["method", "coefficient", "exponent", "predicted_error_at_1e7_dof"])  # Define the stable tail-fit output schema.
        writer.writeheader()  # Emit the fit-table header before the method-specific records.
        writer.writerows(fit_records)  # Persist all fitted parameters and large-DOF predictions for auditability.
    return 0  # Report successful postprocessing after all actual-point, fit, and image artifacts have been written.


if __name__ == "__main__":  # Execute plotting only when this file is invoked directly by the GitHub Actions workflow.
    raise SystemExit(main())  # Run the complete scatter/Pareto postprocessing pipeline and propagate its shell status.
